import * as backend from './backend.js';
import {escape,safeURL,toast,dialogEvents,courseURL,postURL,popupDesigns,popupClass} from './ui.js';
import {editorMarkup,setupRichEditor,readRichEditor} from './richtext.js';
dialogEvents();
let demo=false,current='overview',data={courses:[],posts:[],testimonials:[],reviews:[],comments:[],enquiries:[],popups:[],settings:{}},editing=null,deleteAction=null,started=false;
const collections={courses:'classes',posts:'posts',testimonials:'testimonials',reviews:'reviews',comments:'comments',enquiries:'enquiries',popups:'popups'};
const titles={overview:'Overview',courses:'Masterclasses',posts:'The journal',testimonials:'Student stories',reviews:'Review moderation',comments:'Article comments',enquiries:'Your inbox',popups:'Announcements',settings:'Site settings'};
const content=document.querySelector('#admin-content');
const uid=()=>crypto.randomUUID();
const e=escape;
function normalize(c){return {...c,title:c.title?.replace(/&amp;/g,'&')||c.pageTitle||'',description:c.description||c.pageDesc||'',summary:c.summary||c.desc||'',image:c.image||c.flyerUrl||'',checkout:c.checkout||c.selarLink||'',category:c.category||'Construction',level:c.level||'Skill builder',published:c.published!==false&&!c.hidden};}
async function defaults(){const [courses,posts,settings]=await Promise.all(['catalog.json','posts.json','settings.json'].map(async p=>{const r=await fetch('/'+p);return r.json();}));return {courses,posts,settings,testimonials:Array.from({length:9},(_,i)=>({id:'t'+(i+1),image:'assets/testimonials/t'+(i+1)+'.jpg',alt:'Original student feedback '+(i+1),published:true,order:i+1})),reviews:[],comments:[],enquiries:[],popups:[]};}
async function load(){if(demo){data=await defaults();return;}const entries=await Promise.all(Object.entries(collections).map(async([key,col])=>[key,await backend.list(col)]));for(const [key,values] of entries)data[key]=key==='courses'?values.map(normalize):key==='testimonials'?values.map(x=>({...x,image:x.image||x.imgUrl||x.url||'',published:x.published!==false&&!x.hidden})):values;data.settings=await backend.get('content','public')||{};}
async function openWorkspace(isDemo){demo=isDemo;document.querySelector('#workspace-mode').textContent=demo?'DESIGN PREVIEW · Changes stay in memory and reset on reload.':'LIVE WORKSPACE · Changes are saved to your Firebase project.';document.querySelector('#login-view').hidden=true;document.querySelector('#workspace').hidden=false;content.innerHTML='<p>Loading your academy…</p>';try{await load();render();}catch{content.innerHTML='<div class="notice">The workspace could not read live data. Check your administrator role and deployed security rules.</div>';}}
async function persist(key,id,payload){if(!demo)await backend.save(collections[key],id,payload);const arr=data[key],i=arr.findIndex(x=>x.id===id);if(i>=0)arr[i]={...arr[i],...payload,id};else arr.push({...payload,id});}
function switchTab(tab){current=tab;document.querySelector('#workspace-title').textContent=titles[tab];document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));render();}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
document.querySelector('#demo-button').addEventListener('click',()=>openWorkspace(true));
document.querySelector('#login-form').addEventListener('submit',async event=>{event.preventDefault();const f=event.target,v=Object.fromEntries(new FormData(f)),button=f.querySelector('button');button.disabled=true;document.querySelector('#login-status').textContent='Checking secure access…';try{await backend.login(v.email,v.password);f.reset();await openWorkspace(false);}catch(err){document.querySelector('#login-status').textContent=backend.configured?'Unable to sign in. Check your credentials, verified email and administrator role.':err.message;}finally{button.disabled=false;}});
document.querySelector('#logout-button').addEventListener('click',async()=>{if(!demo)await backend.logout();demo=false;data={courses:[],posts:[],testimonials:[],reviews:[],comments:[],enquiries:[],popups:[],settings:{}};document.querySelector('#workspace').hidden=true;document.querySelector('#login-view').hidden=false;document.querySelector('#editor-modal').close();});
if(backend.configured)backend.watchAuth(user=>{if(user&&!demo&&!started){started=true;openWorkspace(false);}else if(!user&&!demo){document.querySelector('#workspace').hidden=true;document.querySelector('#login-view').hidden=false;started=false;}}).catch(()=>{document.querySelector('#login-status').textContent='Backend connection unavailable.';});
let idleTimer;for(const ev of ['pointerdown','keydown'])document.addEventListener(ev,()=>{clearTimeout(idleTimer);if(!demo&&!document.querySelector('#workspace').hidden)idleTimer=setTimeout(()=>document.querySelector('#logout-button').click(),20*60*1000);});
function overview(){return `<div class="metrics"><div class="metric"><strong>${data.courses.length}</strong><span>MASTERCLASSES</span></div><div class="metric"><strong>${data.posts.filter(x=>x.published).length}</strong><span>PUBLISHED STORIES</span></div><div class="metric"><strong>${data.reviews.filter(x=>!x.approved).length+data.comments.filter(x=>!x.approved).length}</strong><span>REVIEWS & COMMENTS TO CHECK</span></div><div class="metric"><strong>${data.enquiries.filter(x=>x.status==='new').length}</strong><span>NEW ENQUIRIES</span></div></div><div class="admin-card"><p class="eyebrow">YOUR NEXT CHAPTER</p><h2>Good things grow<br><em>with a little attention.</em></h2><p>Keep your class details current, publish helpful journal stories and give every enquiry a considered reply.</p><div class="actions"><button class="btn" data-jump="posts">Write a story ↗</button><button class="btn outline" data-jump="popups">Create an announcement</button></div></div><div class="admin-card"><h3>Launch essentials</h3><p>${demo?'This is a preview. No backend credentials are bundled. Connect your Firebase project using SETUP.md to save live changes.':'The live workspace is connected. Deploy the included security rules and enforce App Check before accepting public submissions.'}</p><p>Export public content and run the included build script when you publish new courses or articles. This creates crawlable HTML and updates the sitemap.</p><button class="btn outline small" id="seed-button">${demo?'Reset preview content':'Import original classes & journal'}</button><p class="status">Import adds missing items only and preserves existing records.</p></div>`;}
function row(key,x){const title=x.title||x.alt||x.name||'Untitled',status=['reviews','comments'].includes(key)?(x.approved?'Approved':'Pending'):key==='enquiries'?x.status:(x.published?'Published':'Draft');const extra=key==='posts'?x.category:key==='courses'?x.fee:['reviews','comments'].includes(key)?x.comment:key==='enquiries'?x.message:key==='popups'?x.message:x.alt;return `<article class="admin-row">${key==='courses'||key==='testimonials'?`<img src="${e(safeURL(x.image,{image:true}))}" alt="${e(title)}">`:''}<div class="row-copy"><span class="pill">${e(status)}</span><h3>${e(title)}</h3><p>${e(extra||'')}</p>${key==='comments'?`<p>Article: ${e(data.posts.find(p=>p.id===x.postId)?.title||x.postId)}</p>`:''}${key==='enquiries'?`<p>${e(x.email)} · ${e(x.course)} · ${e(x.tag||'Untagged')}</p>`:''}</div><div class="row-actions">${['reviews','comments'].includes(key)&&!x.approved?`<button class="btn small" data-approve="${e(x.id)}" data-key="${key}">Approve</button>`:''}${key==='enquiries'?`<a class="btn outline small" href="mailto:${e(encodeURIComponent(x.email||''))}?subject=${encodeURIComponent('Your ISew enquiry')}">Reply by email ↗</a>`:''}${!['reviews','comments'].includes(key)?`<button class="btn outline small" data-edit="${e(x.id)}" data-key="${key}">${key==='enquiries'?'Manage':'Edit'}</button>`:''}${key==='courses'?`<a class="btn outline small" href="${courseURL(x)}" target="_blank" rel="noopener">View ↗</a>`:''}${key==='posts'&&x.published?`<a class="btn outline small" href="${postURL(x)}" target="_blank" rel="noopener">View ↗</a>`:''}<button class="btn outline small danger" data-delete="${e(x.id)}" data-key="${key}">Remove</button></div></article>`;}
function settings(){const s=data.settings;return `<form id="settings-form" class="admin-card"><h2>The academy’s voice.</h2><div class="form-grid">${field('headline','Homepage headline','text',s.headline||'',true,180)}${field('intro','Homepage introduction','textarea',s.intro||'',true,1200)}${field('email','Contact email','email',s.email||'',false,200)}${field('whatsapp','WhatsApp number (country code, digits only)','text',s.whatsapp||'',false,15)}</div><button class="btn" type="submit">Save settings ↗</button><p class="status">These settings update live text and contact links. Use the build script with your domain for canonical URLs and SEO snapshots.</p></form>`;}
function render(){if(current==='overview')content.innerHTML=overview();else if(current==='settings')content.innerHTML=settings();else{const values=data[current]||[];content.innerHTML=`<div class="toolbar"><h2>${e(titles[current])}</h2>${!['reviews','comments','enquiries'].includes(current)?`<button class="btn small" data-add="${current}">Add ${current==='posts'?'story':current==='popups'?'announcement':'item'} +</button>`:''}</div>${current==='popups'?'<div class="notice">Announcements support dates, page targeting, delay and frequency. Only enabled, published announcements appear to visitors.</div>':''}<div class="admin-card">${values.length?values.map(x=>row(current,x)).join(''):'<p class="status">Nothing here yet. This space is ready for your next chapter.</p>'}</div>`;}}
function field(name,label,type,value,full=false,max=200){const input=type==='textarea'?`<textarea name="${name}" maxlength="${max}" required>${e(value)}</textarea>`:type==='checkbox'?`<input type="checkbox" name="${name}" ${value?'checked':''}>`:type==='select'?`<select name="${name}">${['Construction','Embellishment'].map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('')}</select>`:type==='file'?`<input type="file" name="${name}" accept="image/jpeg,image/png,image/webp">`:`<input name="${name}" type="${type}" value="${e(value)}" ${type==='number'?'min="0" max="999"':''} ${['startsAt','endsAt','upload','image'].includes(name)?'':'required'} maxlength="${max}">`;return `<label class="field ${full?'full':''} ${type==='checkbox'?'check':''}">${type==='checkbox'?input+e(label):e(label)+input}</label>`;}
function edit(key,id){document.querySelector('#editor-form').oninput=null;document.querySelector('#editor-modal').classList.remove('editor-fullscreen');const x=(data[key]||[]).find(y=>y.id===id)||{},f=[];editing={key,id:id||uid(),fresh:!id};document.querySelector('#editor-title').textContent=(id?'Edit ':'Create ')+(key==='posts'?'a journal story':key==='popups'?'an announcement':key==='courses'?'a masterclass':key==='enquiries'?'enquiry details':'a student story');
if(key==='courses'){f.push(field('title','Class title','text',x.title||'',true,160),field('summary','Short introduction','textarea',x.summary||'',true,600),field('description','Full description','textarea',x.description||'',true,5000),field('fee','Fee and alternative currencies','text',x.fee||''),field('duration','Duration / delivery','text',x.duration||''),field('category','Category','select',x.category||'Construction'),field('level','Experience level','text',x.level||'Skill builder'),field('checkout','HTTPS Selar checkout link','url',x.checkout||''),field('order','Display order','number',x.order||1),field('image','Image path or HTTPS URL','text',x.image||'/assets/courses/corset.jpg',true,2000),field('upload','Or upload a new image (5 MB max)','file','',true),field('published','Publish this course','checkbox',x.published??false,true));}
if(key==='posts'){f.push(field('title','Article title','text',x.title||'',true,180),field('slug','URL slug (lowercase words with hyphens)','text',x.slug||'',true,100),field('category','Category','text',x.category||'Studio notes'),field('date','Publish date','date',x.date||new Date().toISOString().slice(0,10)),field('excerpt','Search / preview description','textarea',x.excerpt||'',true,300),editorMarkup(),field('image','Image path or HTTPS URL','text',x.image||'/assets/hero/hero-2.jpg',true,2000),field('upload','Or upload an article image','file','',true),field('published','Publish this article','checkbox',x.published??false,true));}
if(key==='testimonials'){f.push(field('alt','Description of the original feedback','text',x.alt||'',true,200),field('image','Image path or HTTPS URL','text',x.image||'',true,2000),field('upload','Or upload the original screenshot','file','',true),field('order','Display order','number',x.order||1),field('published','Publish this story (with consent)','checkbox',x.published??false,true));}
if(key==='popups'){f.push(popupPicker(x.design||'atelier'),field('title','Announcement headline','text',x.title||'',true,180),field('message','Message','textarea',x.message||'',true,1200),field('buttonLabel','Button text','text',x.buttonLabel||'Explore classes'),field('url','Button path or HTTPS URL','text',x.url||'/courses.html',false,2000),field('page','Page path or “all”','text',x.page||'all'),field('delaySeconds','Delay in seconds (3–120)','number',x.delaySeconds||12),field('frequencyDays','Show again after this many days','number',x.frequencyDays||7),field('priority','Priority (higher wins)','number',x.priority||0),field('startsAt','Start date/time (optional, your local time)','datetime-local',localDate(x.startsAt)),field('endsAt','End date/time (optional, your local time)','datetime-local',localDate(x.endsAt)),field('enabled','Enable this announcement','checkbox',x.enabled??false),field('published','Publish to website','checkbox',x.published??false));}
if(key==='enquiries'){f.push(field('tag','Internal tag','text',x.tag||'General',true,80));f.push(`<label class="field">Status<select name="status">${['new','in-progress','resolved'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></label>`);}
document.querySelector('#editor-fields').innerHTML=f.join('');document.querySelector('#editor-status').textContent='';document.querySelector('#editor-modal').classList.toggle('editor-wide',key==='posts'||key==='popups');document.querySelector('#editor-modal').showModal();if(key==='posts')setupRichEditor(x.bodyHtml,x.body);if(key==='popups')setupPopupPreview();}
function localDate(s){if(!s)return '';const d=new Date(s);if(isNaN(d))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function validatedURL(x){const u=new URL(x,location.origin);if(u.protocol!=='https:'&&u.origin!==location.origin)throw new Error('Use a local path or an HTTPS address.');if(!['http:','https:'].includes(u.protocol))throw new Error('Invalid link.');return x;}
document.querySelector('#editor-form').addEventListener('submit',async event=>{event.preventDefault();if(!editing)return;const f=event.target,key=editing.key,id=editing.id,v=Object.fromEntries(new FormData(f)),button=f.querySelector('[type="submit"]');button.disabled=true;try{if(key==='posts'){Object.assign(v,readRichEditor());if(!v.body||v.body.length>20000||v.bodyHtml.length>60000)throw new Error('Write an article of 1–20,000 characters.');}for(const checkbox of f.querySelectorAll('[type="checkbox"]'))v[checkbox.name]=checkbox.checked;for(const n of ['order','delaySeconds','frequencyDays','priority'])if(n in v)v[n]=Number(v[n]);for(const n of ['image','url'])if(v[n])validatedURL(v[n]);if(v.checkout){const u=new URL(v.checkout);if(u.protocol!=='https:'||!['selar.com','www.selar.com'].includes(u.hostname))throw new Error('Use an HTTPS Selar checkout link.');}if(v.slug&&!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(v.slug))throw new Error('Use lowercase words separated by hyphens for the slug.');if(v.slug&&data.posts.some(x=>x.slug===v.slug&&x.id!==id))throw new Error('That article slug is already in use.');if(key==='popups'){if(!popupDesigns.includes(v.design))throw new Error('Choose an announcement design.');if(v.page!=='all'&&!/^\/[a-z0-9/.-]*$/.test(v.page))throw new Error('Use “all” or a page path such as /courses.html.');if(v.delaySeconds<3||v.delaySeconds>120||v.frequencyDays<1||v.frequencyDays>365)throw new Error('Use a delay of 3–120 seconds and a frequency of 1–365 days.');for(const n of ['startsAt','endsAt'])v[n]=v[n]?new Date(v[n]).toISOString():'';if(v.startsAt&&v.endsAt&&v.endsAt<=v.startsAt)throw new Error('The end must be later than the start.');}
const file=v.upload;delete v.upload;if(file?.size){if(demo)throw new Error('Image uploads require the live backend. You can use an existing image path in preview.');v.image=await backend.upload(file,key==='posts'?'journal':key==='testimonials'?'testimonials':'classes');}
if(['courses','posts','testimonials'].includes(key)&&!v.image)throw new Error('Choose an image or upload a file.');await persist(key,id,v);document.querySelector('#editor-modal').close();render();toast(demo?'Preview updated in memory.':'Changes saved to the academy.');}catch(err){document.querySelector('#editor-status').textContent=err.message||'Could not save.';}finally{button.disabled=false;}});
content.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.jump)switchTab(b.dataset.jump);if(b.dataset.add)edit(b.dataset.add);if(b.dataset.edit)edit(b.dataset.key,b.dataset.edit);if(b.dataset.delete){deleteAction={key:b.dataset.key,id:b.dataset.delete};document.querySelector('#delete-modal').showModal();}if(b.dataset.approve){try{await persist(b.dataset.key||'reviews',b.dataset.approve,{approved:true});render();toast('Comment or review approved.');}catch{toast('Could not approve this review.');}}if(b.id==='seed-button'){b.disabled=true;try{if(demo){data=await defaults();}else{const original=await defaults();for(const key of ['courses','posts','testimonials'])for(const item of original[key]){const existing=data[key].find(x=>x.id===item.id);if(!existing)await persist(key,item.id,item);else if(key==='courses')await persist(key,existing.id,normalize(existing));else if(key==='testimonials')await persist(key,existing.id,{image:existing.image,alt:existing.alt||'Original student feedback',order:existing.order||item.order,published:existing.published});};if(!data.settings.headline){data.settings=original.settings;await backend.save('content','public',data.settings);}}render();toast(demo?'Preview reset.':'Missing original content imported.');}catch{toast('Import could not finish. Check your rules and retry; existing items are preserved.');b.disabled=false;}}});
document.querySelector('#confirm-delete').addEventListener('click',async()=>{if(!deleteAction)return;const {key,id}=deleteAction,b=document.querySelector('#confirm-delete');b.disabled=true;try{if(!demo)await backend.remove(collections[key],id);data[key]=data[key].filter(x=>x.id!==id);document.querySelector('#delete-modal').close();render();toast(demo?'Item removed from preview.':'Item removed. Rebuild your SEO snapshot to remove its static page.');deleteAction=null;}catch{toast('The item could not be removed.');}finally{b.disabled=false;}});
content.addEventListener('submit',async event=>{if(event.target.id!=='settings-form')return;event.preventDefault();const f=event.target,v=Object.fromEntries(new FormData(f)),b=f.querySelector('button');b.disabled=true;try{if(!/^\d{10,15}$/.test(v.whatsapp))throw new Error('Use 10–15 digits including the country code.');if(!demo)await backend.save('content','public',v);data.settings=v;toast(demo?'Preview settings saved in memory.':'Live settings saved.');}catch(err){toast(err.message);}finally{b.disabled=false;}});
document.querySelector('#export-button').addEventListener('click',()=>{const snapshot={schemaVersion:1,exportedAt:new Date().toISOString(),courses:data.courses,posts:data.posts,testimonials:data.testimonials,popups:data.popups,settings:data.settings};const blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='isew-content-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Public content exported. Private enquiries and pending reviews are excluded.');});
function popupPicker(selected){return `<fieldset class="popup-picker full"><legend>Choose a card design</legend><div class="popup-design-grid">${popupDesigns.map((d,i)=>`<label class="popup-option"><input type="radio" name="design" value="${d}" ${d===selected?'checked':''}><span class="popup-mini ${popupClass(d)}"><span class="mini-flower" aria-hidden="true">✳</span><strong>${['The Atelier','Golden Hour','Studio Postcard','The Ribbon'][i]}</strong><span>A little inspiration.</span><i>Explore ↗</i></span><span class="popup-option-label">${['Editorial / Chocolate','Sculpted / Ochre','Framed / Clay','Ribbon / Rose'][i]}</span></label>`).join('')}</div></fieldset><div class="popup-live-wrap full"><p class="eyebrow">LIVE CARD PREVIEW</p><div class="popup-live" id="popup-live"><span class="popup-ornament" aria-hidden="true">✳</span><p class="eyebrow">A NOTE FROM THE ACADEMY</p><h2 id="popup-preview-title">A beautiful next chapter.</h2><p id="popup-preview-message">Your announcement will appear here.</p><span class="btn" id="popup-preview-button">Explore classes ↗</span></div></div>`;}
function setupPopupPreview(){const form=document.querySelector('#editor-form');function update(){const v=Object.fromEntries(new FormData(form)),preview=document.querySelector('#popup-live');preview.className='popup-live '+popupClass(v.design);document.querySelector('#popup-preview-title').textContent=v.title||'A beautiful next chapter.';document.querySelector('#popup-preview-message').textContent=v.message||'Your announcement will appear here.';document.querySelector('#popup-preview-button').textContent=v.buttonLabel||'Explore classes ↗';}form.oninput=update;update();}
